cat > /tmp/design.py << 'PYEOF'
import RNA, random, sys
target = open('/tmp/target.txt').read().strip()
N = len(target)
# parse pairs
stack=[]; pairs=[]
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')': pairs.append((stack.pop(), i))
pairpos = {}
for (i,j) in pairs: pairpos[i]=j; pairpos[j]=i
# fc
md = RNA.md(); md.dangles=2; md.noLP=0
fc = RNA.fold_compound(target, md)  # placeholder; we fold sequences
def fold_seq(seq):
    fc2 = RNA.fold_compound(seq, md)
    ss, mfe = fc2.mfe()
    return ss, mfe
# distance: count mismatched base pairs vs target
def bp_set(ss):
    s=[]; 
    for i,c in enumerate(ss):
        if c=='(': s.append(i)
        elif c==')': 
            if s: s.pop()
    return set()
def score(ss):
    # compare dot-bracket equality and bp distance
    if ss==target: return 0
    # bp distance via ViennaRNA
    return RNA.bp_distance(ss, target)

# init: GC pairs, A loops
def init_seq():
    seq=['A']*N
    for (i,j) in pairs:
        seq[i]='G'; seq[j]='C'
    return ''.join(seq)

best = init_seq()
bss, bmfe = fold_seq(best)
bscore = score(bss)
print('init score:', bscore, 'mfe:', bmfe, 'match:', bss==target, file=sys.stderr)
cur = best; cur_score=bscore
import time
t0=time.time()
it=0
while time.time()-t0 < 90 and cur_score>0:
    it+=1
    # pick a position to mutate
    p = random.randrange(N)
    if p in pairpos:
        q=pairpos[p]
        # change pair type
        choices=[('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')]
        a,b=random.choice(choices)
        cand = cur[:p]+a+cur[p+1:q]+b+cur[q+1:]
    else:
        c=random.choice('ACGU')
        cand = cur[:p]+c+cur[p+1:]
    css, cmfe = fold_seq(cand)
    cs = score(css)
    if cs < cur_score or (cs==cur_score and cmfe<bmfe-1e-9):
        cur=cand; cur_score=cs
        if cs<bscore or (cs==bscore and cmfe<bmfe):
            best=cand; bss=css; bmfe=cmfe; bscore=cs
            print('it',it,'best score',bscore,'mfe',round(bmfe,2),'match',bss==target, file=sys.stderr)
print('total it', it, 'final score', bscore, 'match', bss==target, file=sys.stderr)
print(best)
PYEOF
